<?php
declare(strict_types=1);
if(getenv('COUPONHUB_RUN_DB_TEST')!=='1')exit("SKIP isolated DB opt-in required\n");
require __DIR__.'/../app/bootstrap.php';
use App\Core\{Database,HttpError,ValidationException};
use App\Repositories\{ExternalOfferRepository,CouponRepository,AdminCouponRepository,AdminRepository,CampaignRepository};
use App\Services\{CouponService,AccesstradeService};
$db=Database::connection();
if((int)$db->query('SELECT @@port')->fetchColumn()!==13379 || $db->query('SELECT DATABASE()')->fetchColumn()!=='couponhub_merge_test')throw new RuntimeException('Unsafe database');
$n=0;
function externalCheck(bool $ok,string $label):void{global $n;if(!$ok)throw new RuntimeException('FAIL '.$label);++$n;echo 'PASS '.$label.PHP_EOL;}
function externalReject(callable $call,string $label):void{try{$call();}catch(RuntimeException|mysqli_sql_exception $e){externalCheck(true,$label);return;}throw new RuntimeException('FAIL accepted '.$label);}
$aid=(int)$db->query("SELECT id FROM users WHERE username='admin_demo'")->fetchColumn();
$uid=(int)$db->query("SELECT id FROM users WHERE username='user_demo'")->fetchColumn();
$writer=(int)$db->query("SELECT id FROM users WHERE username='merchant_shops'")->fetchColumn();
$other=(int)$db->query("SELECT id FROM users WHERE username='merchant_services'")->fetchColumn();
$merchant=(int)$db->query("SELECT merchant_id FROM merchant_memberships WHERE user_id=$writer AND status='ACTIVE' ORDER BY merchant_id LIMIT 1")->fetchColumn();
$cat=(int)$db->query('SELECT id FROM categories WHERE is_active=1 LIMIT 1')->fetchColumn();
$repo=new ExternalOfferRepository($db);$coupons=new CouponRepository($db);$service=new CouponService($coupons);$adminCoupons=new AdminCouponRepository($db);$admin=new AdminRepository($db);$campaigns=new CampaignRepository($db);
externalCheck($repo->ready(),'additive provider table available');
$suffix=bin2hex(random_bytes(5));$code='ACCEPT_'.$suffix;
$row=['external_key'=>hash('sha256',$suffix),'provider_id'=>$suffix,'code'=>$code,'payload'=>['title'=>'External acceptance','merchant_ref'=>'provider-ref','source_url'=>'https://example.com/offer','description'=>'plain text','terms'=>'confirmed conditions']];
externalReject(fn()=>$repo->stage($uid,[$row]),'ordinary user cannot stage sources');
$repo->stage($aid,[$row]);$repo->stage($aid,[$row]);
$stmt=$db->prepare('SELECT id FROM external_offers WHERE external_key=?');$stmt->execute([$row['external_key']]);$id=(int)$stmt->fetchColumn();
externalCheck((int)$db->query('SELECT COUNT(*) FROM external_offers')->fetchColumn()===1,'repeat source fetch is idempotent');
$input=['merchant_id'=>(string)$merchant,'category_id'=>(string)$cat,'title'=>'External acceptance','code'=>$code,'description'=>'source fixture','terms'=>'Minimum order and expiry independently checked','discount_type'=>'PERCENTAGE','discount_value'=>'10','min_order_amount'=>'100000','max_discount_amount'=>'30000','usage_channel'=>'ONLINE','promotion_url'=>'https://example.com/offer','starts_at'=>date('Y-m-d\TH:i:s',time()-3600),'ends_at'=>date('Y-m-d\TH:i:s',time()+86400*4)];
foreach([['discount_value'=>'1e309'],['min_order_amount'=>'INF'],['max_discount_amount'=>'100000000000000'],['title'=>['bad']],['code'=>"BAD\nCODE"]] as $bad)externalReject(fn()=>$service->validateSubmission(array_replace($input,$bad)),'malformed nested/nonfinite/control input rejected');
$data=$service->validateSubmission($input);$expectedFingerprint=$repo->find($id)['fingerprint'];
externalReject(fn()=>$repo->import($uid,$id,$data,$expectedFingerprint),'ordinary user cannot import pending coupon');
$coupon=$repo->import($aid,$id,$data,$expectedFingerprint);
$created=$adminCoupons->find($coupon);
externalCheck($created['source']==='COMMUNITY' && $created['moderation_status']==='PENDING' && $coupons->findPublic($coupon)===null,'external import remains pending and nonpublic, never falsely OFFICIAL');
externalCheck($repo->find($id)['state']==='IMPORTED' && (int)$repo->find($id)['coupon_id']===$coupon,'source and coupon persist atomically');
externalReject(fn()=>$repo->import($aid,$id,$data,$expectedFingerprint),'double import blocked');
$coupons->moderate($aid,$coupon,'APPROVED','ENABLED','Accepted test fixture');
externalCheck($coupons->findPublic($coupon)!==null,'independent moderation publishes imported coupon');
$adminCoupons->revoke($aid,$coupon,'Provider coupon revoked during acceptance');
$acceptedFingerprint=$repo->find($id)['imported_fingerprint'];
$row['payload']['title']='Changed upstream title';$repo->stage($aid,[$row]);
externalCheck($repo->find($id)['fingerprint']!==$acceptedFingerprint && $repo->find($id)['imported_fingerprint']===$acceptedFingerprint,'changed source retains import fingerprint for admin warning');

externalCheck($repo->find($id)['state']==='IMPORTED' && $adminCoupons->find($coupon)['publication_status']==='ARCHIVED' && $coupons->findPublic($coupon)===null,'upstream refresh never resurrects a revoked public coupon');
externalReject(fn()=>$coupons->moderate($aid,$coupon,'APPROVED','ENABLED','Attempt revival'),'moderation cannot restore archived coupon');
externalReject(fn()=>$adminCoupons->update($aid,$coupon,$data),'admin edit cannot restore archived coupon');
$copy=$row;$copy['external_key']=hash('sha256','copy'.$suffix);$repo->stage($aid,[$copy]);
$stmt->execute([$copy['external_key']]);$copyId=(int)$stmt->fetchColumn();
$oldFingerprint=$repo->find($copyId)['fingerprint'];$copy['payload']['description']='Updated while review was open';$repo->stage($aid,[$copy]);
externalReject(fn()=>$repo->import($aid,$copyId,array_replace($data,['code'=>'NEW_'.$suffix]),$oldFingerprint),'stale review cannot accept a newer unseen source revision');
$copyFingerprint=$repo->find($copyId)['fingerprint'];
externalReject(fn()=>$repo->import($aid,$copyId,$data,$copyFingerprint),'another source cannot duplicate a revoked code in the same window');
externalCheck($repo->find($copyId)['state']==='PENDING' && $repo->find($copyId)['coupon_id']===null,'failed import rolls back staging state');
$repo->dismiss($aid,$copyId);$repo->stage($aid,[$copy]);
externalCheck($repo->find($copyId)['state']==='DISMISSED','provider refresh preserves dismissal');
externalReject(fn()=>$repo->import($aid,$copyId,array_replace($data,['code'=>'DIFFERENT_'.$suffix]),$copyFingerprint),'dismissed source cannot be imported');
$start=gmdate('Y-m-d H:i:s',time()-3600);$end=gmdate('Y-m-d H:i:s',time()+86400*4);
$campaign=$campaigns->create($writer,$merchant,'Revocation acceptance','accept-'.$suffix,null,$start,$end,'PUBLISHED');
externalCheck($campaigns->findPublic($campaign)!==null,'approved shop campaign is initially visible');
externalReject(fn()=>$campaigns->updateOwned($campaign,$other,'Cross merchant',null,$start,$end,'PUBLISHED'),'another merchant cannot edit a campaign');
$admin->setCampaignStatus($campaign,'DISABLED',$aid);
externalCheck($campaigns->findPublic($campaign)===null,'admin disable removes campaign from public view');
externalReject(fn()=>$campaigns->updateOwned($campaign,$writer,'Revive',null,$start,$end,'PUBLISHED'),'owner cannot override admin campaign disable');
$admin->setCampaignStatus($campaign,'PUBLISHED',$aid);
externalCheck($campaigns->findPublic($campaign)!==null,'admin can deliberately undo temporary disable');
$admin->setCampaignStatus($campaign,'ARCHIVED',$aid);
externalReject(fn()=>$admin->setCampaignStatus($campaign,'PUBLISHED',$aid),'archived campaign cannot be republished by admin');
externalReject(fn()=>$campaigns->updateOwned($campaign,$writer,'Revive',null,$start,$end,'PUBLISHED'),'archived campaign cannot be republished by owner');
$expired=$campaigns->create($aid,null,'Expired draft','expired-'.$suffix,null,gmdate('Y-m-d H:i:s',time()-86400*3),gmdate('Y-m-d H:i:s',time()-86400),'DRAFT');
externalReject(fn()=>$admin->setCampaignStatus($expired,'PUBLISHED',$aid),'past campaign cannot be newly published');
$active=(int)$db->query("SELECT c.id FROM v_coupon_status c WHERE c.merchant_id=$merchant AND source='OFFICIAL' AND effective_status='ACTIVE' ORDER BY id LIMIT 1")->fetchColumn();
externalReject(fn()=>$coupons->disableOwnedOfficial($other,$active),'cross-shop coupon disable denied');
$adminCoupons->revoke($aid,$active,'Acceptance withdrawal of official coupon');
externalReject(fn()=>$coupons->disableOwnedOfficial($writer,$active),'owner cannot change terminal coupon through disable');
externalReject(fn()=>$coupons->updateOwnedOfficial($writer,$active,$data),'owner cannot edit withdrawn official coupon');
$db->prepare("UPDATE users SET role='USER' WHERE id=?")->execute([$aid]);
externalReject(fn()=>$repo->stage($aid,[$row]),'stale admin role cannot stage at repository layer');
$db->prepare("UPDATE users SET role='ADMIN' WHERE id=?")->execute([$aid]);
echo "PASS $n external source / revocation database checks on disposable fixture only.\n";
